import { registerApp } from "@larksuiteoapi/node-sdk";
import { spawnSync } from "../process/exec.js";
import qrcode from "qrcode-terminal";
import { createLogger } from "../log.js";
import { guideScopeImport } from "./scopes-setup.js";
import { configureBridgeApp } from "./app-setup.js";
import { saveBridgeSecret } from "./bridge-secrets.js";
import { ensureLarkCli } from "./lark-cli-install.js";

const log = createLogger("wizard");

function showQrCode(url: string, expireIn: number): void {
  process.stdout.write(`\n请用飞书 App 扫描下方二维码（${expireIn}s 内有效）:\n\n`);
  qrcode.generate(url, { small: true });
  process.stdout.write("\n");

  // Open the auth page in the default browser (shows a scannable QR too).
  const opened =
    process.platform === "darwin"
      ? spawnSync("open", [url], { stdio: "ignore" })
      : process.platform === "win32"
        ? spawnSync("rundll32", ["url.dll,FileProtocolHandler", url], { stdio: "ignore" })
        : spawnSync("xdg-open", [url], { stdio: "ignore" });
  if (opened.status === 0) {
    process.stdout.write("已在浏览器中打开授权页。\n");
  }

  process.stdout.write(`链接（备用）: ${url}\n\n`);
}

export interface SetupOptions {
  profileName?: string;
  larkCliPath?: string;
  domain?: "feishu" | "lark";
}

export interface SetupResult {
  appId: string;
  profileName: string;
}

/**
 * QR-code onboarding via SDK registerApp, then register credentials in
 * lark-cli so the bridge can load them the usual way.
 */
export async function runSetupWizard(opts: SetupOptions = {}): Promise<SetupResult> {
  const profileName = opts.profileName ?? "lark-opencode-bridge";
  const domain = opts.domain ?? "feishu";

  const lark = await ensureLarkCli({
    larkCliPath: opts.larkCliPath,
    installIfMissing: true,
    upgradeToLatest: true,
  });
  if (!lark.ok) {
    throw new Error(lark.error ?? "lark-cli 不可用");
  }
  const larkCli = lark.larkCliPath;

  process.stdout.write("\n=== lark-opencode-bridge 扫码绑定 ===\n\n");
  process.stdout.write("请用飞书 App 扫描下方二维码，授权后 bridge 会自动保存凭证。\n\n");

  const result = await registerApp({
    ...(domain === "lark"
      ? { larkDomain: "accounts.larksuite.com" }
      : { domain: "accounts.feishu.cn" }),
    source: "lark-opencode-bridge",
    onQRCodeReady: (info) => {
      showQrCode(info.url, info.expireIn);
    },
    onStatusChange: (info) => {
      if (info.status === "polling") process.stdout.write("等待扫码…\n");
      if (info.status === "slow_down") process.stdout.write("轮询降速，请尽快完成扫码…\n");
    },
  });

  const appId = result.client_id;
  const appSecret = result.client_secret;
  log.info(`registerApp ok appId=${appId}`);

  // SDK's tenant_brand can be undefined or other strings; coerce to the two
  // valid lark-cli values so we don't accidentally pass `"undefined"` as
  // `--brand` and mis-tag the saved profile.
  const rawBrand = result.user_info?.tenant_brand;
  const brand: "feishu" | "lark" =
    rawBrand === "lark" || rawBrand === "feishu" ? rawBrand : domain;
  // Persist the credentials FIRST — the app is already created on the Feishu
  // side, so a profile-add hiccup must not lose the secret (re-running the
  // wizard would create a duplicate app).
  await saveBridgeSecret({
    appId,
    appSecret,
    brand: brand === "lark" ? "lark" : "feishu",
    profile: profileName,
  });

  const runProfileAdd = () =>
    spawnSync(
      larkCli,
      [
        "profile",
        "add",
        "--name",
        profileName,
        "--app-id",
        appId,
        "--brand",
        brand,
        "--app-secret-stdin",
      ],
      { input: appSecret, encoding: "utf8" },
    );

  let add = runProfileAdd();
  // Re-running the wizard creates a NEW app but reuses the same profile name,
  // so a leftover profile from a previous (possibly failed) run makes
  // profile add fail with "already exists" / "already used by profile".
  // The name is bridge-owned — replace the stale entry and retry once.
  if (add.status !== 0 && /already (exists|used)/i.test(`${add.stdout || ""}${add.stderr || ""}`)) {
    process.stdout.write(`检测到旧的 profile "${profileName}"（上次向导残留），正在替换…\n`);
    const rm = spawnSync(larkCli, ["profile", "remove", profileName], { encoding: "utf8" });
    if (rm.status !== 0) {
      log.warn(`profile remove ${profileName} failed: ${(rm.stderr || rm.stdout || "").trim()}`);
    }
    add = runProfileAdd();
  }
  if (add.status !== 0) {
    const detail = [
      `exit=${add.status ?? "spawn-error"}`,
      add.error ? `error=${add.error.message}` : "",
      (add.stderr || "").trim() && `stderr=${add.stderr.trim()}`,
      (add.stdout || "").trim() && `stdout=${add.stdout.trim()}`,
    ]
      .filter(Boolean)
      .join(" | ");
    const manualCmd =
      process.platform === "win32"
        ? `echo <secret>| lark-cli profile add --name ${profileName} --app-id ${appId} --brand ${brand} --app-secret-stdin --use\n（cmd 下 <secret> 不要加引号，| 前不要有空格；PowerShell 用 '<secret>' | lark-cli …）`
        : `echo '<secret>' | lark-cli profile add --name ${profileName} --app-id ${appId} --brand ${brand} --app-secret-stdin --use`;
    throw new Error(
      `lark-cli profile add failed (${detail || "no output"})\n` +
        `凭证已保存（appId=${appId}），无需重跑向导、不要重新扫码（会重复建应用）。\n` +
        `手动补一条 profile 即可（<secret> 见 ~/.lark-opencode-bridge/secrets.json）：\n` +
        `  ${manualCmd}`,
    );
  }

  const use = spawnSync(larkCli, ["profile", "use", profileName], { encoding: "utf8" });
  if (use.status !== 0) {
    log.warn(`profile use failed: ${(use.stderr || "").trim()}`);
  }

  process.stdout.write(`\n绑定成功！appId=${appId} profile=${profileName}\n`);
  await guideScopeImport(appId, brand === "lark" ? "lark" : "feishu");
  await configureBridgeApp({
    appId,
    appSecret,
    brand: brand === "lark" ? "lark" : "feishu",
    ownerOpenId: result.user_info?.open_id,
  });
  process.stdout.write("全部完成后运行: npm start\n\n");
  return { appId, profileName };
}
